// For reachability checks
int head[MAXN], nxt[MAXM], to[MAXM], ecnt;
int rhead[MAXN], rnxt[MAXM], rto[MAXM], recnt;
int reach1[MAXN], reachN[MAXN];
int queue[MAXN];
ll dist[MAXN];

void addEdge(int u, int v) {
    to[ecnt] = v; nxt[ecnt] = head[u]; head[u] = ecnt++;
}
void addREdge(int u, int v) {
    rto[recnt] = v; rnxt[recnt] = rhead[u]; rhead[u] = recnt++;
}

void bfs(int src, int* adj_head, int* adj_nxt, int* adj_to, int* visited) {
    int front = 0, back = 0;
    queue[back++] = src;
    visited[src] = 1;
    while (front < back) {
        int u = queue[front++];
        for (int e = adj_head[u]; e != -1; e = adj_nxt[e]) {
            int v = adj_to[e];
            if (!visited[v]) { visited[v] = 1; queue[back++] = v; }
        }
    }
}

