    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *rhead = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        rhead[i] = -1;
    }

    Node *g = (Node *)malloc(sizeof(Node) * M);
    Node *rg = (Node *)malloc(sizeof(Node) * M);
    int gcnt = 0, rgcnt = 0;

    for (int i = 0; i < M; i++) {
        int a, b;
        ll c;
        scanf("%d %d %lld", &a, &b, &c);
        edges[i].a = a;
        edges[i].b = b;
        edges[i].c = c;

        g[gcnt].to = b;
        g[gcnt].next = head[a];
        head[a] = gcnt++;

        rg[rgcnt].to = a;
        rg[rgcnt].next = rhead[b];
        rhead[b] = rgcnt++;
    }

    // Reachable from 1
    bool *from1 = (bool *)calloc(N + 1, sizeof(bool));
    int *queue = (int *)malloc(sizeof(int) * (N + 5));
    int ql = 0, qr = 0;
    queue[qr++] = 1;
    from1[1] = true;
    while (ql < qr) {
        int v = queue[ql++];
        for (int e = head[v]; e != -1; e = g[e].next) {
            int to = g[e].to;
            if (!from1[to]) {
                from1[to] = true;
                queue[qr++] = to;
            }
        }
    }

    // Can reach N
    bool *toN = (bool *)calloc(N + 1, sizeof(bool));
    ql = qr = 0;
    queue[qr++] = N;
    toN[N] = true;
    while (ql < qr) {
        int v = queue[ql++];
        for (int e = rhead[v]; e != -1; e = rg[e].next) {
            int to = rg[e].to;
            if (!toN[to]) {
                toN[to] = true;
                queue[qr++] = to;
            }
        }
    }

    // Bellman-Ford for maximum path:
    // dist[b] < dist[a] + c  => relax
    const ll NEG_INF = -(1LL << 60);
    ll *dist = (ll *)malloc(sizeof(ll) * (N + 1));
    for (int i = 1; i <= N; i++) dist[i] = NEG_INF;
    dist[1] = 0;

    for (int i = 1; i <= N - 1; i++) {
        bool updated = false;
        for (int j = 0; j < M; j++) {
            int a = edges[j].a, b = edges[j].b;
            ll c = edges[j].c;
            if (dist[a] == NEG_INF) continue;
            if (dist[b] < dist[a] + c) {
                dist[b] = dist[a] + c;
                updated = true;
            }
        }
        if (!updated) break;
    }

    // Check positive cycle affecting path 1 -> ... -> N
    for (int j = 0; j < M; j++) {
        int a = edges[j].a, b = edges[j].b;
        ll c = edges[j].c;
        if (dist[a] == NEG_INF) continue;
        if (dist[b] < dist[a] + c) {
            if (from1[a] && toN[b]) {
                printf("inf\n");
                free(edges); free(head); free(rhead); free(g); free(rg);
                free(from1); free(toN); free(queue); free(dist);
                return 0;
            }
        }
    }

    printf("%lld\n", dist[N]);

    free(edges);
    free(head);
    free(rhead);
    free(g);
    free(rg);
    free(from1);
    free(toN);
    free(queue);
    free(dist);

    return 0;
}

