        q.pop();
        for (int to : g[v]) {
            if (!from1[to]) {
                from1[to] = 1;
                q.push(to);
            }
        }
    }

    // Can reach N
    toN[N] = 1;
    q.push(N);
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int to : rg[v]) {
            if (!toN[to]) {
                toN[to] = 1;
                q.push(to);
            }
        }
    }

