            if (dist[e.b] < dist[e.a] + e.c) {
                dist[e.b] = dist[e.a] + e.c;
                updated = true;
            }
        }
        if (!updated) break;
    }

    // If we can still improve on the N-th relaxation
    // through a node that is on some path 1 -> ... -> N,
    // then answer is infinite.
    for (auto &e : edges) {
        if (dist[e.a] == -INF) continue;
        if (dist[e.b] < dist[e.a] + e.c) {
