            this.w = w;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        List<Edge> edges = new ArrayList<>();
        List<Integer>[] g = new ArrayList[N + 1];
        List<Integer>[] rg = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            long c = fs.nextLong();
            edges.add(new Edge(a, b, c));
            g[a].add(b);
            rg[b].add(a);
        }

        boolean[] fromStart = new boolean[N + 1];
        boolean[] toEnd = new boolean[N + 1];

        dfsIterative(1, g, fromStart);
        dfsIterative(N, rg, toEnd);

        long NEG = Long.MIN_VALUE / 4;
        long[] dist = new long[N + 1];
        Arrays.fill(dist, NEG);
        dist[1] = 0;

        for (int i = 1; i <= N - 1; i++) {
            boolean updated = false;
            for (Edge e : edges) {
                if (!fromStart[e.from] || !toEnd[e.to]) continue;
                if (dist[e.from] == NEG) continue;
                if (dist[e.to] < dist[e.from] + e.w) {
                    dist[e.to] = dist[e.from] + e.w;
                    updated = true;
                }
            }
            if (!updated) break;
        }

        for (Edge e : edges) {
            if (!fromStart[e.from] || !toEnd[e.to]) continue;
            if (dist[e.from] == NEG) continue;
            if (dist[e.to] < dist[e.from] + e.w) {
                System.out.println("inf");
                return;
            }
        }

        System.out.println(dist[N]);
    }

    static void dfsIterative(int start, List<Integer>[] graph, boolean[] vis) {
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        vis[start] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : graph[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    stack.push(v);
                }
            }
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))

    edges = []
    for _ in range(m):
        a = int(next(it)) - 1  # 0-indexed
        b = int(next(it)) - 1
        w = int(next(it))
        edges.append((a, b, w))

    # Bellman-Ford for maximum path
    INF = -10**18
    dist = [INF] * n
    dist[0] = 0

    # Relax edges n-1 times
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w > dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break

    # Now detect positive cycles reachable from 1 and can reach N
    # We need to do one more relaxation pass to find nodes affected by positive cycles
    in_cycle = [False] * n
    for _ in range(n):
        for u, v, w in edges:
            if dist[u] != INF and dist[u] + w > dist[v]:
                dist[v] = dist[u] + w
                in_cycle[v] = True
            if in_cycle[u]:
                in_cycle[v] = True

    # Check if any node in a positive cycle can reach node N-1
    # Build reverse graph for reachability to N
    rev_adj = [[] for _ in range(n)]
    for u, v, _ in edges:
        rev_adj[v].append(u)

    # BFS/DFS from N-1 in reverse graph to find nodes that can reach N
    can_reach_n = [False] * n
    can_reach_n[n-1] = True
    q = deque([n-1])
    while q:
        node = q.popleft()
        for prev in rev_adj[node]:
            if not can_reach_n[prev]:
                can_reach_n[prev] = True
                q.append(prev)

    # Also check from node 1 forward
    adj = [[] for _ in range(n)]
    for u, v, _ in edges:
        adj[u].append(v)

    reachable_from_1 = [False] * n
    reachable_from_1[0] = True
    q = deque([0])
    while q:
        node = q.popleft()
        for nxt in adj[node]:
            if not reachable_from_1[nxt]:
                reachable_from_1[nxt] = True
                q.append(nxt)

    # Check if any node in a positive cycle is reachable from 1 and can reach N
    for i in range(n):
        if in_cycle[i] and reachable_from_1[i] and can_reach_n[i]:
            print(-1)
            return

    if dist[n-1] == INF:
        print(-1)
    else:
        print(dist[n-1])

if __name__ == "__main__":
    solve()
